{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C03","C15","C17","C07","C13","C18","C21","C24","C30","C31","C06","C08","C25","C26","C27","C32"],
  "contradictory_card_ids": ["C16","C20","C29"],
  "prediction_basis_card_ids": ["C15","C13","C08","C03","C17"],
  "claims": [
    {
      "claim": "In patients with cirrhosis, bumetanide—a loop diuretic with acidic ionizable groups—had absolute oral bioavailability of 0.95 after 1 mg oral vs IV, also reported as 95%; L2 reports 95–100%.",
      "card_ids": ["C03","C15","C17"]
    },
    {
      "claim": "In patients with alcoholic cirrhosis, tolfenamic acid had absolute oral bioavailability of about 100% after 100 mg p.o. vs i.v.; L2 patient-level values were 91–126% and the mean was 113 ± 11%.",
      "card_ids": ["C07","C13","C18","C21","C24","C30","C31"]
    },
    {
      "claim": "In patients with cirrhosis, isradipine had mean systemic availability of 36.9% (also reported as 37%; L2 reports 41%, and 28 ± 14% in cirrhotic patients without shunts), all above the 20% threshold.",
      "card_ids": ["C06","C08","C25","C26","C27","C32"]
    },
    {
      "claim": "The query is a pyridine-sulfonylurea loop diuretic; the closest supplied cirrhosis-context analog, bumetanide, shows high oral bioavailability, supporting F >= 20%.",
      "card_ids": ["C03","C15","C17"]
    },
    {
      "claim": "L3 oral exposure records for sulfonylureas (gliclazide M01, tolbutamide M08) show measurable plasma Cmax/AUC after oral dosing, consistent with oral absorption, but lack IV comparators and are not query-specific; they do not establish F for torasemide.",
      "card_ids": ["C61","C82","C36","C77","C65","C80","C43","C44","C51"]
    },
    {
      "claim": "Low-F L2 records (IQG-607 in mice ~4%; KNI-272 syrup 15.7%) are from different molecules, species, and conditions and do not transfer to the query.",
      "card_ids": ["C16","C20","C29"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "low",
      "direction": "supportive",
      "decision_effect": "no_change",
      "card_ids": ["C61","C82","C36","C77","C65","C80","C43","C44","C51","C74","C79"]
    }
  ],
  "evidence_gaps": [
    "No direct torasemide bioavailability record in cirrhosis is supplied; prediction relies on transfer from related contexts.",
    "The physicochemical prior is based on computed properties only; no experimental permeability, solubility, or first-pass data for the query.",
    "Cirrhosis severity, portal shunting, formulation, and dose effects on the query are not specified.",
    "L3 oral exposure records lack IV comparators and are for other molecules, so they cannot provide absolute F for the query.",
    "Low-F L2 records are from non-transferable contexts and do not resolve query-specific uncertainty."
  ],
  "decision_summary": "All materially relevant cirrhosis-context records—bumetanide (F=95%), tolfenamic acid (~100%), and isradipine (37%)—support F >= 20%; L3 oral exposure records are consistent with oral absorption for related sulfonylureas but provide no direct F evidence and do not change the decision. Prediction: high."
}

